@app.route('/api/admin/save-config', methods=['POST'])
def save_admin_config():
    """Save API configuration to .env file"""
    try:
        data = request.get_json()

        # Read existing .env file
        env_path = os.path.join(os.path.dirname(__file__), '.env')
        env_lines = []

        if os.path.exists(env_path):
            with open(env_path, 'r') as f:
                env_lines = f.readlines()

        # Configuration keys to update
        config_keys = {
            'NAC_API_KEY': data.get('nac_api_key', ''),
            'NEXUS_API_KEY': data.get('nexus_api_key', ''),
            'NEXUS_URL': data.get('nexus_url', ''),
            'NEXUS_USERNAME': data.get('nexus_username', '')
        }

        # Update or add configuration
        updated_keys = set()
        for i, line in enumerate(env_lines):
            for key, value in config_keys.items():
                if line.startswith(f'{key}='):
                    env_lines[i] = f'{key}={value}\n'
                    updated_keys.add(key)
                    break

        # Add new keys that weren't found
        for key, value in config_keys.items():
            if key not in updated_keys:
                env_lines.append(f'{key}={value}\n')

        # Write back to .env file
        with open(env_path, 'w') as f:
            f.writelines(env_lines)

        return jsonify({
            'status': 'success',
            'message': 'Configuration saved successfully'
        })

    except Exception as e:
        return jsonify({
            'status': 'error',
            'message': f'Failed to save configuration: {str(e)}'
        }), 500


