def save_admin_config():
    """Save API configuration to YAML file"""
    try:
        data = request.get_json()

        # Create yaml directory if it doesn't exist
        yaml_dir = os.path.join(os.path.dirname(__file__), 'yaml')
        os.makedirs(yaml_dir, exist_ok=True)

        # Configuration file path
        config_path = os.path.join(yaml_dir, 'config.yaml')

        # Configuration data
        config_data = {
            'nac': {
                'api_key': data.get('nac_api_key', '')
            },
            'nexus_dashboard': {
                'api_key': data.get('nexus_api_key', ''),
                'url': data.get('nexus_url', ''),
                'username': data.get('nexus_username', '')
            }
        }

        # Write to YAML file
        with open(config_path, 'w') as f:
            yaml.dump(config_data, f, default_flow_style=False, sort_keys=False)

        return jsonify({
            'status': 'success',
            'message': 'Configuration saved successfully'
        })

    except Exception as e:
        return jsonify({
            'status': 'error',
            'message': f'Failed to save configuration: {str(e)}'
        }), 500


@app.route('/api/admin/load-config', methods=['GET'])
def load_admin_config():
    """Load current API configuration from YAML file"""
    try:
        # Configuration file path
        yaml_dir = os.path.join(os.path.dirname(__file__), 'yaml')
        config_path = os.path.join(yaml_dir, 'config.yaml')

        # Check if config file exists
        if not os.path.exists(config_path):
            return jsonify({
                'status': 'success',
                'data': {
                    'nac_api_key': '',
                    'nexus_api_key': '',
                    'nexus_url': '',
                    'nexus_username': ''
                }
            })

        # Read YAML file
        with open(config_path, 'r') as f:
            config_data = yaml.safe_load(f) or {}

        return jsonify({
            'status': 'success',
            'data': {
                'nac_api_key': config_data.get('nac', {}).get('api_key', ''),
                'nexus_api_key': config_data.get('nexus_dashboard', {}).get('api_key', ''),
                'nexus_url': config_data.get('nexus_dashboard', {}).get('url', ''),
                'nexus_username': config_data.get('nexus_dashboard', {}).get('username', '')
            }
        })
    except Exception as e:
        return jsonify({
            'status': 'error',
            'message': f'Failed to load configuration: {str(e)}'
        }), 500


@app.route('/api/admin/clear-config', methods=['POST'])
def clear_admin_config():
    """Clear API configuration from .env file"""
    try:
        # Read existing .env file
        env_path = os.path.join(os.path.dirname(__file__), '.env')
        env_lines = []

        if os.path.exists(env_path):
            with open(env_path, 'r') as f:
                env_lines = f.readlines()

        # Remove configuration keys
        config_keys = ['NAC_API_KEY', 'NEXUS_API_KEY', 'NEXUS_URL', 'NEXUS_USERNAME']
        filtered_lines = [line for line in env_lines
                         if not any(line.startswith(f'{key}=') for key in config_keys)]

        # Write back to .env file
        with open(env_path, 'w') as f:
            f.writelines(filtered_lines)

        return jsonify({
            'status': 'success',
            'message': 'Configuration cleared successfully'
        })

    except Exception as e:
        return jsonify({
            'status': 'error',
            'message': f'Failed to clear configuration: {str(e)}'
        }), 500


@app.errorhandler(404)
def not_found(error):
    """Handle 404 errors"""
    return jsonify({'error': 'Not found', 'status': 'error'}), 404


@app.errorhandler(500)
def internal_error(error):
    """Handle 500 errors"""
    return jsonify({'error': 'Internal server error', 'status': 'error'}), 500


if __name__ == '__main__':
