/* Custom styles for Flask Bootstrap App with Left Sidebar */

:root {
    --primary-gradient: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    --card-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
    --hover-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
    --sidebar-width: 250px;
    --sidebar-bg: #0d6efd;
    --sidebar-hover: #0b5ed7;
    --sidebar-active: #0a58ca;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    min-height: 100vh;
    overflow-x: hidden;
}

/* Wrapper Layout */
.wrapper {
    display: flex;
    width: 100%;
    min-height: 100vh;
}

/* Sidebar Styles */
.sidebar {
    min-width: var(--sidebar-width);
    max-width: var(--sidebar-width);
    background: var(--sidebar-bg);
    color: #fff;
    transition: all 0.3s ease;
    position: fixed;
    top: 0;
    left: 0;
    height: 100vh;
    z-index: 999;
    overflow-y: auto;
    box-shadow: 2px 0 5px rgba(0, 0, 0, 0.1);
}

.sidebar.collapsed {
    margin-left: calc(-1 * var(--sidebar-width));
}

.sidebar-header {
    padding: 1.5rem 1rem;
    background: rgba(0, 0, 0, 0.1);
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.sidebar-header h4 {
    color: #fff;
    font-weight: 600;
    text-align: center;
}

.sidebar-logo {
    max-width: 160px;
    height: auto;
    opacity: 1;
}

.sidebar-header .small {
    font-size: 0.75rem;
    letter-spacing: 0.5px;
}

.sidebar-nav {
    list-style: none;
    padding: 1rem 0;
    margin: 0;
}

.sidebar-item {
    margin-bottom: 0.5rem;
}

.sidebar-link {
    display: flex;
    align-items: center;
    padding: 0.875rem 1.25rem;
    color: rgba(255, 255, 255, 0.85);
    text-decoration: none;
    transition: all 0.3s ease;
    border-left: 3px solid transparent;
}

.sidebar-link:hover {
    background: var(--sidebar-hover);
    color: #fff;
    border-left-color: #fff;
}

.sidebar-link.active {
    background: var(--sidebar-active);
    color: #fff;
    border-left-color: #fff;
    font-weight: 600;
}

.sidebar-link i {
    margin-right: 0.75rem;
    font-size: 1.25rem;
}

/* Sidebar Parent/Tree Items */
.sidebar-parent {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.875rem 1.25rem;
    color: rgba(255, 255, 255, 0.95);
    text-decoration: none;
    transition: all 0.3s ease;
    border-left: 3px solid transparent;
    font-weight: 600;
    cursor: pointer;
}

.sidebar-parent:hover {
    background: var(--sidebar-hover);
    color: #fff;
    border-left-color: rgba(255, 255, 255, 0.5);
}

.sidebar-parent i:first-child {
    margin-right: 0.75rem;
    font-size: 1.25rem;
}

.sidebar-arrow {
    margin-left: auto;
    font-size: 0.875rem;
    transition: transform 0.3s ease;
}

.sidebar-parent[aria-expanded="true"] .sidebar-arrow {
    transform: rotate(180deg);
}

.sidebar-parent[aria-expanded="false"] .sidebar-arrow {
    transform: rotate(0deg);
}

/* Submenu Styles */
.sidebar-submenu {
    list-style: none;
    padding: 0;
    margin: 0;
    background: rgba(0, 0, 0, 0.15);
}

.sidebar-submenu .sidebar-link {
    padding-left: 3rem;
    font-size: 0.95rem;
    border-left: 3px solid transparent;
}

.sidebar-submenu .sidebar-link i {
    font-size: 1rem;
}

.sidebar-submenu .sidebar-link:hover {
    background: var(--sidebar-hover);
    border-left-color: rgba(255, 255, 255, 0.7);
}

.sidebar-submenu .sidebar-link.active {
    background: var(--sidebar-active);
    border-left-color: #fff;
}

/* Sidebar Divider */
.sidebar-divider {
    height: 1px;
    margin: 1rem 0;
    background: rgba(255, 255, 255, 0.2);
    list-style: none;
}

/* Main Content Area */
.main {
    flex: 1;
    margin-left: var(--sidebar-width);
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    transition: all 0.3s ease;
    width: calc(100% - var(--sidebar-width));
}

.main.expanded {
    margin-left: 0;
    width: 100%;
}

/* Card enhancements */
.card {
    transition: transform 0.3s ease, box-shadow 0.3s ease;
    border: none;
}

.card:hover {
    transform: translateY(-5px);
    box-shadow: var(--hover-shadow);
}

/* Feature icons */
.feature-icon {
    display: inline-block;
    padding: 1rem;
    background: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);
    border-radius: 50%;
}

/* API response styling */
#apiResponseContent {
    background-color: #f8f9fa;
    border-radius: 0.25rem;
    padding: 1rem;
    max-height: 300px;
    overflow-y: auto;
    font-family: 'Courier New', monospace;
    font-size: 0.9rem;
}

/* Form styling */
.form-control:focus {
    border-color: #667eea;
    box-shadow: 0 0 0 0.2rem rgba(102, 126, 234, 0.25);
}

/* Button enhancements */
.btn {
    transition: all 0.3s ease;
}

.btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
}

/* Navbar customization */
.navbar {
    box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
}

/* Footer */
footer {
    margin-top: auto;
}

/* Top Navbar in Main Area */
.main .navbar {
    position: sticky;
    top: 0;
    z-index: 100;
    box-shadow: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.075);
}

#sidebarToggle {
    padding: 0.375rem 0.75rem;
}

/* Content Area */
.main .container-fluid {
    flex: 1;
}

/* Smooth scrolling */
html {
    scroll-behavior: smooth;
}

/* Responsive Design */
@media (max-width: 768px) {
    .sidebar {
        margin-left: calc(-1 * var(--sidebar-width));
    }

    .sidebar.show {
        margin-left: 0;
    }

    .main {
        margin-left: 0;
        width: 100%;
    }

    /* Overlay when sidebar is open on mobile */
    .sidebar.show::before {
        content: '';
        position: fixed;
        top: 0;
        left: var(--sidebar-width);
        width: calc(100vw - var(--sidebar-width));
        height: 100vh;
        background: rgba(0, 0, 0, 0.5);
        z-index: 998;
    }
}

/* Page Content Management */
.page-content {
    display: none;
    opacity: 0;
    animation: fadeIn 0.4s ease-out forwards;
}

.page-content.active {
    display: block;
}

.page-header {
    padding-bottom: 1rem;
    border-bottom: 2px solid #e9ecef;
}

.page-header h2 {
    font-weight: 600;
    color: #333;
    margin-bottom: 0.5rem;
}

.page-header .text-muted {
    font-size: 1rem;
}

/* Loading animation */
@keyframes fadeIn {
    from {
        opacity: 0;
        transform: translateY(20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.card {
    animation: fadeIn 0.6s ease-out;
}

/* Responsive typography */
@media (max-width: 768px) {
    .display-4 {
        font-size: 2.5rem;
    }

    .lead {
        font-size: 1rem;
    }
}

/* Pre tag styling */
pre {
    white-space: pre-wrap;
    word-wrap: break-word;
}

/* Alert animations */
.alert {
    animation: fadeIn 0.3s ease-out;
}

/* Custom scrollbar for code blocks */
#apiResponseContent::-webkit-scrollbar {
    width: 8px;
}

#apiResponseContent::-webkit-scrollbar-track {
    background: #f1f1f1;
    border-radius: 4px;
}

#apiResponseContent::-webkit-scrollbar-thumb {
    background: #888;
    border-radius: 4px;
}

#apiResponseContent::-webkit-scrollbar-thumb:hover {
    background: #555;
}

